-- GRANSHI Content Development Project: hierarchical 800-topic tracker.
-- Seeded as a private Admin work plan; this does not publish public pages.
CREATE TABLE IF NOT EXISTS content_projects (
 id INTEGER PRIMARY KEY CHECK(id=1), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS content_plan_departments (
 id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL DEFAULT 1 REFERENCES content_projects(id) ON DELETE CASCADE,
 code TEXT NOT NULL UNIQUE, title_en TEXT NOT NULL, title_ne TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS content_plan_categories (
 id INTEGER PRIMARY KEY AUTOINCREMENT, department_id INTEGER NOT NULL REFERENCES content_plan_departments(id) ON DELETE CASCADE,
 code TEXT NOT NULL UNIQUE, title_en TEXT NOT NULL, title_ne TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS content_plan_topics (
 id INTEGER PRIMARY KEY AUTOINCREMENT, category_id INTEGER NOT NULL REFERENCES content_plan_categories(id) ON DELETE CASCADE,
 title_en TEXT NOT NULL, title_ne TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed')),
 sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_content_plan_dept_order ON content_plan_departments(project_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_content_plan_category_order ON content_plan_categories(department_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_content_plan_topic_order ON content_plan_topics(category_id,sort_order,id);
INSERT OR IGNORE INTO content_projects(id,title,description,created_at,updated_at) VALUES(1,'GRANSHI – Content Development (800 Pages)','Private Admin project: 8 departments × 10 categories × 10 topics. Topics are a planning checklist only; publishing pages remains a separate workflow.',datetime('now'),datetime('now'));
